#include <stdio.h>
int less_than_n(char a[],int n,char c)
{
    int i=0,count=0;
    while((a[i]!='\0')&&(count<n))
    {
        if(c==a[i])
        {
            count++;
        }
        i++;
    }
    if(count==n)
    return 0;   //if statement is false
    else 
    return 1;   //if statement is true
}
int search(char s1[],char s2[])
{
    int i=0,j=0;
    while((s1[i]!='\0')||(s2[j]!='\0'))
    {
        if(s1[i]==s2[j])
        {
            j++;
            if(s2[j]=='\0')
               {
                  j=-1;
                  break;
               }
            if(s1[i+1]!=s2[j])
               {
                  j=0;
               }
        }
        i++;
    }
    if(j==-1)
    return 1;
    else
    return 0;
}
